// Validate incoming client data
const data = $input.item.json;
const requiredFields = ['name', 'email', 'phone', 'goals', 'preferredCoachingType'];

let missingFields = [];
requiredFields.forEach(field => {
  if (!data[field]) {
    missingFields.push(field);
  }
});

if (missingFields.length > 0) {
  return {
    json: {
      success: false,
      message: `Missing required fields: ${missingFields.join(', ')}`,
      validationError: true
    }
  };
}

// Format and standardize data
return {
  json: {
    ...data,
    name: data.name.trim(),
    email: data.email.toLowerCase().trim(),
    phone: data.phone.replace(/[^0-9+]/g, ''),
    intakeDate: new Date().toISOString(),
    status: 'New',
    success: true
  }
};

// Create a PDF from the welcome packet content
const fs = require('fs');
const path = require('path');
const { jsPDF } = require('jspdf');

// Create a temporary directory for the PDF
const tempDir = '/tmp/welcome-packets';
if (!fs.existsSync(tempDir)) {
  fs.mkdirSync(tempDir, { recursive: true });
}

// Sanitize client name for filename
const sanitizedName = $json.name.replace(/[^a-z0-9]/gi, '_').toLowerCase();
const timestamp = new Date().getTime();
const filename = `welcome_packet_${sanitizedName}_${timestamp}.pdf`;
const filepath = path.join(tempDir, filename);

// Create PDF
const doc = new jsPDF();
const content = $node["OpenAI - Generate Welcome Packet"].json.text;

// Split content into lines that fit on the page
const splitText = doc.splitTextToSize(content, 180);

// Add content to PDF
let y = 10;
const lineHeight = 7;

// Add title
doc.setFontSize(16);
doc.text('Welcome to Your Coaching Journey', 105, y, { align: 'center' });
y += 15;

// Add content
doc.setFontSize(12);
for (let i = 0; i < splitText.length; i++) {
  // Check if we need a new page
  if (y > 280) {
    doc.addPage();
    y = 10;
  }

  doc.text(splitText[i], 15, y);
  y += lineHeight;
}

// Save the PDF
doc.save(filepath);

return {
  json: {
    ...$json,
    welcomePacketPath: filepath,
    welcomePacketFilename: filename
  }
};

